package com.api.server

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.security.SecureRandom
import java.time.Instant
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

case class Session(id: String, userId: Option[String], createdAt: Instant, authenticated: Boolean)
case class RateLimit(count: AtomicInteger, windowStart: Instant)

object SessionManager {
  private val sessions = new ConcurrentHashMap[String, Session]()
  private val rateLimits = new ConcurrentHashMap[String, RateLimit]()
  private val random = new SecureRandom()
  private val hmacKey = new Array[Byte](32)
  random.nextBytes(hmacKey)

  private val RATE_LIMIT_WINDOW_SECONDS = 60
  private val MAX_REQUESTS_PER_WINDOW = 100
  private val MAX_LOGIN_RETRIES = 3

  def generateSessionId(): String = {
    val bytes = new Array[Byte](32)
    random.nextBytes(bytes)
    Base64.getUrlEncoder.withoutPadding().encodeToString(bytes)
  }

  def hmacSign(data: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"))
    Base64.getUrlEncoder.withoutPadding().encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }

  def checkRateLimit(clientIp: String): Boolean = {
    val now = Instant.now()
    val limit = rateLimits.computeIfAbsent(clientIp, _ => RateLimit(new AtomicInteger(0), now))
    if (java.time.Duration.between(limit.windowStart, now).getSeconds > RATE_LIMIT_WINDOW_SECONDS) {
      rateLimits.put(clientIp, RateLimit(new AtomicInteger(1), now))
      true
    } else {
      limit.count.incrementAndGet() <= MAX_REQUESTS_PER_WINDOW
    }
  }

  def getOrCreateSession(requestSessionId: Option[String]): Session = {
    requestSessionId match {
      case Some(sid) =>
        val existing = sessions.get(sid)
        if (existing != null) existing
        else {
          // Session ID provided but not found - could be expired
          // Preserve the session ID for continuity (e.g., retry scenarios)
          val session = Session(sid, None, Instant.now(), authenticated = false)
          sessions.put(sid, session)
          session
        }
      case None =>
        val newId = generateSessionId()
        val session = Session(newId, None, Instant.now(), authenticated = false)
        sessions.put(newId, session)
        session
    }
  }

  def authenticateWithRetry(sessionId: String, username: String, password: String, attempt: Int = 1): Either[String, Session] = {
    if (!checkRateLimit(username)) {
      return Left("Rate limit exceeded. Please try again later.")
    }

    // Simulate authentication check
    val authResult = verifyCredentials(username, password)

    authResult match {
      case Right(_) =>
        // Successful authentication - upgrade the existing session
        val upgradedSession = Session(
          id = sessionId,
          userId = Some(username),
          createdAt = Instant.now(),
          authenticated = true
        )
        sessions.put(sessionId, upgradedSession)
        Right(upgradedSession)
      case Left(err) if attempt < MAX_LOGIN_RETRIES =>
        // Retry logic for transient failures
        Thread.sleep(100 * attempt)
        authenticateWithRetry(sessionId, username, password, attempt + 1)
      case Left(err) =>
        Left(s"Authentication failed after $MAX_LOGIN_RETRIES attempts: $err")
    }
  }

  def verifyCredentials(username: String, password: String): Either[String, Boolean] = {
    // Simulated credential verification with timing-safe comparison
    val storedHash = getStoredPasswordHash(username)
    storedHash match {
      case Some(hash) =>
        val inputHash = hmacSign(password)
        if (java.security.MessageDigest.isEqual(hash.getBytes, inputHash.getBytes)) Right(true)
        else Left("Invalid credentials")
      case None => Left("User not found")
    }
  }

  def getStoredPasswordHash(username: String): Option[String] = {
    // Simulated database lookup
    Some(hmacSign("password123")) // Demo only
  }

  def getSession(sessionId: String): Option[Session] = {
    Option(sessions.get(sessionId))
  }

  def invalidateSession(sessionId: String): Unit = {
    sessions.remove(sessionId)
  }
}

object ApiServer {
  import SessionManager._

  def handleRequest(method: String, path: String, headers: Map[String, String], clientIp: String, body: Map[String, String] = Map.empty): (Int, Map[String, String], String) = {
    if (!checkRateLimit(clientIp)) {
      return (429, Map.empty, "{\"error\": \"Rate limit exceeded\"}")
    }

    val requestSessionId = headers.get("X-Session-Id")
    val session = getOrCreateSession(requestSessionId)

    (method, path) match {
      case ("POST", "/api/login") =>
        val username = body.getOrElse("username", "")
        val password = body.getOrElse("password", "")
        if (username.isEmpty || password.isEmpty) {
          (400, Map("X-Session-Id" -> session.id), "{\"error\": \"Missing credentials\"}")
        } else {
          authenticateWithRetry(session.id, username, password) match {
            case Right(authedSession) =>
              val token = hmacSign(authedSession.id + ":" + authedSession.userId.getOrElse(""))
              (200, Map("X-Session-Id" -> authedSession.id, "X-Auth-Token" -> token), "{\"status\": \"authenticated\"}")
            case Left(err) =>
              (401, Map("X-Session-Id" -> session.id), s"{\"error\": \"$err\"}")
          }
        }

      case ("GET", "/api/profile") =>
        if (session.authenticated) {
          (200, Map("X-Session-Id" -> session.id), s"{\"user\": \"${session.userId.getOrElse("")}\"}")
        } else {
          (401, Map("X-Session-Id" -> session.id), "{\"error\": \"Not authenticated\"}")
        }

      case ("POST", "/api/logout") =>
        invalidateSession(session.id)
        (200, Map.empty, "{\"status\": \"logged out\"}")

      case _ =>
        (404, Map("X-Session-Id" -> session.id), "{\"error\": \"Not found\"}")
    }
  }
}
